	"fmt"
	"time"

	"golang.org/x/time/rate"
)

func main() {
	// 2 tokens/sec, bucket holds up to 2 (starts full).
	lim := rate.NewLimiter(rate.Limit(2), 2)

	fmt.Println(lim.Allow()) // token 1 -> true
	fmt.Println(lim.Allow()) // token 2 -> true
	fmt.Println(lim.Allow()) // empty   -> false

	// Wait blocks until a token refills (~0.5s), then returns nil.
	start := time.Now()
	_ = lim.Wait(context.Background())
	fmt.Printf("waited ~%.0fms\n", time.Since(start).Seconds()*1000)
}

