package solution

import "time"

// Limiter is a token bucket. `now` is injected so tests control time.
type Limiter struct {
	rate   float64       // tokens added per second
	burst  float64       // maximum tokens the bucket can hold
	tokens float64       // current tokens
	last   time.Time     // last time we refilled
	now    func() time.Time
}

func NewLimiter(rate, burst float64, now func() time.Time) *Limiter {
	return &Limiter{
		rate:   rate,
		burst:  burst,
		tokens: burst,      // start full: a fresh client may burst
		last:   now(),
		now:    now,
	}
}

// Allow reports whether one token is available, consuming it if so.
func (l *Limiter) Allow() bool {
	t := l.now()
	// Refill lazily: add tokens proportional to elapsed time, capped at burst.
	elapsed := t.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = t
	}
	if l.tokens >= 1 {
		l.tokens-- // consume one token
		return true
	}
	return false
}

