type entry struct {
	limiter  *rate.Limiter
	lastSeen time.Time
}

type Limiters struct {
	mu      sync.Mutex
	clients map[string]*entry
}

func NewLimiters() *Limiters {
	l := &Limiters{clients: make(map[string]*entry)}
	go l.cleanup() // background eviction of idle clients
	return l
}

func (l *Limiters) get(ip string) *rate.Limiter {
	l.mu.Lock()
	defer l.mu.Unlock()
	e, ok := l.clients[ip]
	if !ok {
		e = &entry{limiter: rate.NewLimiter(1, 5)}
		l.clients[ip] = e
	}
	e.lastSeen = time.Now()
	return e.limiter
}

func (l *Limiters) cleanup() {
	for range time.Tick(time.Minute) {
		l.mu.Lock()
		for ip, e := range l.clients {
			if time.Since(e.lastSeen) > 3*time.Minute {
				delete(l.clients, ip) // evict idle client
			}
		}
		l.mu.Unlock()
	}
}

type SlidingLog struct {
	limit  int
	window time.Duration
	events []time.Time // timestamps of allowed events, oldest first
}

func NewSlidingLog(limit int, window time.Duration) *SlidingLog {
	return &SlidingLog{limit: limit, window: window}
}

func (l *SlidingLog) Allow(now time.Time) bool {
	cutoff := now.Add(-l.window)
	// Drop events that have slid out of the window (front of the slice).
	i := 0
	for i < len(l.events) && !l.events[i].After(cutoff) {
		i++
	}
	l.events = l.events[i:]
	if len(l.events) >= l.limit {
		return false // window is full
	}
	l.events = append(l.events, now)
	return true
}
